"impl Hooks for Ext {
    fn action(&mut self, action: Action) -> Option<Action> {
        let payload = self.call(ACTION_HOOK, serde_json::to_vec(&action).ok()?);
        serde_json::from_slice(&payload).ok()
    }

    fn view(&mut self, view: &mut View) {
        let Ok(payload) = serde_json::to_vec(&*view) else {
            return;
        };
        if let Ok(decorated) = serde_json::from_slice(&self.call(VIEW_HOOK, payload)) {
            *view = decorated;
        }
    }
}
